// Rendering for the Emerging Destinations / Japan deck — REAL data edition.
// Depends on globals: d3, Plot (Observable Plot v0.6), maplibregl — all
// vendored in docs/vendor/ — and REAL (data/aggregates.js, generated by
// analysis/export_aggregates.py). No CDN, no tile server: the deck renders
// self-contained forever (GitHub Pages safe). Layout and interactions mirror
// the prototype/ mock deck; every number is real.

(() => {
  'use strict';

  // ---------- palettes ----------
  const REGION_DOMAIN = ['Europe', 'North America', 'East Asia', 'Southeast Asia',
                         'Oceania', 'Latin America', 'Mid-East & Africa', 'South/Central Asia'];
  const REGION_COLORS = ['#1F77B4', '#59A14F', '#E15759', '#EDC948',
                         '#76B7B2', '#B07AA1', '#9C755F', '#FF9DA7'];
  const GROUP_COLORS = { 'Long-haul': '#0072B2', 'Regional': '#E69F00' };
  const SEASONS = ['Winter', 'Spring', 'Summer', 'Autumn'];

  // Cividis-leaning heatmap ramp; transparent at low end so basemap shows through.
  const HEATMAP_RAMP = [
    'interpolate', ['linear'], ['heatmap-density'],
    0.00, 'rgba(255, 252, 221, 0.00)',
    0.10, 'rgba(251, 228, 137, 0.55)',
    0.30, 'rgba(201, 201, 91, 0.80)',
    0.55, 'rgba(107, 139, 88, 0.88)',
    0.80, 'rgba(31, 78, 121, 0.92)',
    1.00, 'rgba(15, 47, 80, 0.95)'
  ];

  const JAPAN_BBOX = [128.5, 30.5, 146.5, 45.8];

  // ---------- Japan geometry: Natural Earth 10m (public domain) ----------
  // data/japan_geo.js: real coastline (109 polygons) + 47 prefecture
  // boundaries — vector, committed, crisp at every zoom. Replaces the
  // original hand-simplified 4-polygon sketch.
  function japanFeature() {
    return { type: 'Feature', properties: {}, geometry: JAPAN_GEO.land };
  }

  // city labels for orientation (HTML markers — no glyph/font dependencies)
  const CITIES = [
    { name: 'Tokyo',     lat: 35.68, lon: 139.69 },
    { name: 'Osaka',     lat: 34.69, lon: 135.50 },
    { name: 'Kyoto',     lat: 35.01, lon: 135.77 },
    { name: 'Nagoya',    lat: 35.18, lon: 136.91 },
    { name: 'Sapporo',   lat: 43.06, lon: 141.35 },
    { name: 'Sendai',    lat: 38.27, lon: 140.87 },
    { name: 'Kanazawa',  lat: 36.57, lon: 136.66 },
    { name: 'Hiroshima', lat: 34.39, lon: 132.46 },
    { name: 'Fukuoka',   lat: 33.59, lon: 130.40 }
  ];

  // ---------- real cell data ----------
  // REAL.cells rows follow REAL.cell_columns: [lat, lon, remoteness, then
  // W/Sp/Su/A counts per population prefix (LH, RG, and the gated origin
  // regions EU/EA/SE/LA)]. Column positions resolved from the data itself.
  const COL = {};
  REAL.cell_columns.forEach((c, i) => { COL[c] = i; });

  // populations the map picker offers: pooled (= LH + RG = everyone,
  // including the tiny 'Other' bucket) and the eight named origin regions.
  const regionPop = (region, key, chip) => ({
    key, chip, label: region, prefixes: [key],
    color: REGION_COLORS[REGION_DOMAIN.indexOf(region)]
  });
  const POPS = [
    { key: 'pooled', label: 'Pooled — all travelers', chip: 'Pooled',
      prefixes: ['LH', 'RG'], color: '#1A1A1A' },
    regionPop('Europe', 'EU', 'Europe'),
    regionPop('North America', 'NA', 'N America'),
    regionPop('East Asia', 'EA', 'E Asia'),
    regionPop('Southeast Asia', 'SE', 'SE Asia'),
    regionPop('Oceania', 'OC', 'Oceania'),
    regionPop('Latin America', 'LA', 'Lat Am'),
    regionPop('Mid-East & Africa', 'ME', 'ME & Africa'),
    regionPop('South/Central Asia', 'SC', 'S/C Asia')
  ].filter(p => p.prefixes.every(x => COL[`${x}_Winter`] !== undefined));

  // the regions are pairwise disjoint; only pooled overlaps them — ticking
  // one side auto-unticks the other, so summed selections never double-count.
  const REGION_KEYS = POPS.filter(p => p.key !== 'pooled').map(p => p.key);
  const OVERLAP = { pooled: REGION_KEYS };
  for (const k of REGION_KEYS) OVERLAP[k] = ['pooled'];

  function cellCount(row, prefixes, season) {
    let n = 0;
    for (const p of prefixes) {
      if (season === 'all') {
        for (const s of SEASONS) n += row[COL[`${p}_${s}`]];
      } else {
        n += row[COL[`${p}_${season}`]];
      }
    }
    return n;
  }

  function cellFeatures() {
    return {
      type: 'FeatureCollection',
      features: REAL.cells.map((row, i) => ({
        type: 'Feature',
        properties: { i, lat: row[0], lon: row[1], remoteness: row[2], t: 0, n: 0 },
        geometry: { type: 'Point', coordinates: [row[1], row[0]] }
      }))
    };
  }

  // ---------- tooltip ----------
  const tooltip = (() => {
    const el = document.createElement('div');
    el.className = 'tooltip';
    document.body.appendChild(el);
    return {
      show(html, x, y) {
        el.innerHTML = html;
        el.style.left = (x + 12) + 'px';
        el.style.top = (y + 12) + 'px';
        el.style.opacity = '1';
      },
      hide() { el.style.opacity = '0'; }
    };
  })();

  // ---------- map base style ----------
  // NO external tiles — sea color + the hand-simplified Japan land fill,
  // rendered locally. History: the prototype's CARTO endpoint now demands an
  // API key, tile.openstreetmap.org 403s website embedding (OSMF policy),
  // and any hosted basemap is a dependency that can die; this one cannot.
  function basemapStyle() {
    return {
      version: 8,
      sources: {
        'japan-land': { type: 'geojson', data: japanFeature() },
        'japan-prefs': { type: 'geojson', data: JAPAN_GEO.prefectures }
      },
      layers: [
        { id: 'sea', type: 'background',
          paint: { 'background-color': '#E7ECF0' } },
        { id: 'land', type: 'fill', source: 'japan-land',
          paint: { 'fill-color': '#FBFAF5' } },
        { id: 'pref-lines', type: 'line', source: 'japan-prefs',
          paint: { 'line-color': '#C9C4B8', 'line-width': 0.6,
                   'line-opacity': 0.8 } },
        { id: 'coast', type: 'line', source: 'japan-land',
          paint: { 'line-color': '#9AA4AC', 'line-width': 0.8 } }
      ]
    };
  }

  // ---------- assign density given population prefixes + season ----------
  function applyDensity(fc, prefixes, season) {
    const logVals = [];
    for (const f of fc.features) {
      const n = cellCount(REAL.cells[f.properties.i], prefixes, season);
      f.properties.n = n;
      if (n > 0) logVals.push(Math.log(n));
    }
    const sorted = logVals.slice().sort(d3.ascending);
    const min = d3.quantile(sorted, 0.05) ?? 0;
    const max = d3.quantile(sorted, 0.99) ?? 1;
    for (const f of fc.features) {
      const n = f.properties.n;
      const t = n > 0
        ? Math.max(0, Math.min(1, (Math.log(n) - min) / (max - min || 1)))
        : 0;
      f.properties.t = t;
    }
    return fc;
  }

  // ---------- create one Japan map ----------
  // cfg: { mapId, statId, labelId, picksId, takeId, defaults } — each panel
  // owns a checkbox selection of POPS; ticked populations are SUMMED into
  // one heatmap. 'pooled' is exclusive (it already is everyone).
  function createMap(cfg) {
    const bbox = JAPAN_BBOX;
    const center = [(bbox[0] + bbox[2]) / 2, (bbox[1] + bbox[3]) / 2];

    const map = new maplibregl.Map({
      container: cfg.mapId,
      style: basemapStyle(),
      center,
      zoom: 4.2,
      attributionControl: { compact: true },
      cooperativeGestures: false
    });

    map.addControl(new maplibregl.NavigationControl({ showCompass: false }), 'top-right');

    const points = cellFeatures();
    let currentSeason = 'all';
    const selection = new Set(cfg.defaults);

    const selected = () => POPS.filter(p => selection.has(p.key));
    const prefixes = () => [...new Set(selected().flatMap(p => p.prefixes))];
    const labelOf = () => selected().map(p => p.label).join(' + ')
      + (selection.has('pooled') ? '' : ' travelers');
    const isDefault = () => selection.size === cfg.defaults.length
      && cfg.defaults.every(k => selection.has(k));

    function refreshOverlay() {
      const lab = document.getElementById(cfg.labelId);
      if (lab) {
        lab.innerHTML = selected().map(p =>
          `<span class="dot" style="background:${p.color}"></span>`).join('')
          + labelOf();
      }
      const take = document.getElementById(cfg.takeId);
      if (take) take.style.display = isDefault() ? '' : 'none';
    }

    function syncPicks() {
      const wrap = document.getElementById(cfg.picksId);
      if (!wrap) return;
      [...wrap.querySelectorAll('.pick')].forEach((el, i) => {
        const on = selection.has(POPS[i].key);
        el.classList.toggle('on', on);
        el.querySelector('input').checked = on;
      });
    }

    function toggle(pop, cb) {
      if (cb.checked) {
        for (const k of (OVERLAP[pop.key] || [])) selection.delete(k);
        selection.add(pop.key);
      } else {
        selection.delete(pop.key);
        if (selection.size === 0) selection.add(pop.key);   // keep ≥ 1 ticked
      }
      syncPicks();
      refresh();
    }

    (function buildPicks() {
      const wrap = document.getElementById(cfg.picksId);
      if (!wrap) return;
      wrap.innerHTML = '';
      for (const p of POPS) {
        const lab = document.createElement('label');
        lab.className = 'pick' + (selection.has(p.key) ? ' on' : '');
        const cb = document.createElement('input');
        cb.type = 'checkbox';
        cb.checked = selection.has(p.key);
        cb.setAttribute('aria-label', `Include ${p.label} photos on this map`);
        cb.addEventListener('change', () => toggle(p, cb));
        const dot = document.createElement('i');
        dot.className = 'pick-dot';
        dot.style.background = p.color;
        lab.append(cb, dot, document.createTextNode(p.chip));
        wrap.appendChild(lab);
      }
    })();

    applyDensity(points, prefixes(), currentSeason);
    refreshOverlay();

    const refit = () => {
      map.resize();
      const isNarrow = window.innerWidth < 600;
      map.fitBounds([[bbox[0], bbox[1]], [bbox[2], bbox[3]]], {
        padding: isNarrow ? { top: 14, bottom: 14, left: 10, right: 10 }
                          : { top: 28, bottom: 28, left: 24, right: 24 },
        duration: 0,
        animate: false
      });
    };

    map.on('load', () => {
      refit();
      setTimeout(refit, 80);
      setTimeout(refit, 320);

      // ---- heatmap source: real visited cells weighted by t ----
      map.addSource('cell-points', { type: 'geojson', data: points });

      // ---- heatmap layer ----
      map.addLayer({
        id: 'cell-heat',
        type: 'heatmap',
        source: 'cell-points',
        paint: {
          // 3.5k real cells are much denser than the mock's ~600 hex
          // centroids — smaller radius + lower intensity or Honshu saturates
          // into one blob.
          'heatmap-weight': [
            'interpolate', ['linear'], ['get', 't'],
            0, 0.0,
            0.3, 0.18,
            0.7, 0.65,
            1, 1.0
          ],
          'heatmap-intensity': [
            'interpolate', ['linear'], ['zoom'],
            0, 0.25,
            4, 0.55,
            7, 0.9,
            10, 1.2
          ],
          'heatmap-radius': [
            'interpolate', ['linear'], ['zoom'],
            0, 2, 3, 6, 5, 13, 7, 26, 9, 48
          ],
          'heatmap-opacity': 0.93,
          'heatmap-color': HEATMAP_RAMP
        }
      });

      // ---- coastline restated on top of the heatmap ----
      map.addLayer({
        id: 'country-line',
        type: 'line',
        source: 'japan-land',
        paint: {
          'line-color': '#1A1A1A',
          'line-width': 0.7,
          'line-opacity': 0.35
        }
      });

      // ---- city labels (HTML markers; pointer-events disabled in CSS) ----
      for (const c of CITIES) {
        const el = document.createElement('div');
        el.className = 'map-city';
        el.textContent = c.name;
        new maplibregl.Marker({ element: el }).setLngLat([c.lon, c.lat]).addTo(map);
      }

      // ---- invisible circle layer for hover hit-testing ----
      map.addLayer({
        id: 'cells-hit',
        type: 'circle',
        source: 'cell-points',
        paint: {
          'circle-radius': 9,
          'circle-color': '#000',
          'circle-opacity': 0
        }
      });

      // hover tooltip
      map.on('mousemove', 'cells-hit', (e) => {
        if (!e.features.length) return;
        const f = e.features[0];
        map.getCanvas().style.cursor = 'crosshair';
        const p = f.properties;
        const seasonLabel = currentSeason === 'all' ? 'All seasons' : currentSeason;
        tooltip.show(
          `<strong>${labelOf()}</strong>`
          + `<div class="tt-row">Photos here: <strong>${Number(p.n).toLocaleString()}</strong> (${seasonLabel})</div>`
          + `<div class="tt-row">Cell remoteness: <strong>${Number(p.remoteness).toFixed(2)}</strong></div>`
          + `<div class="tt-row">${Number(p.lat).toFixed(2)}°N, ${Number(p.lon).toFixed(2)}°E</div>`,
          e.originalEvent.clientX, e.originalEvent.clientY
        );
      });
      map.on('mouseleave', 'cells-hit', () => {
        map.getCanvas().style.cursor = '';
        tooltip.hide();
      });

      updateStats(points, cfg.statId);
    });

    function refresh() {
      applyDensity(points, prefixes(), currentSeason);
      const src = map.getSource('cell-points');
      if (src) src.setData(points);
      updateStats(points, cfg.statId);
      refreshOverlay();
    }

    function update(season) {
      currentSeason = season;
      refresh();
    }

    return { map, update, refit };
  }

  function updateStats(points, statId) {
    const el = document.getElementById(statId);
    if (!el) return;
    const active = points.features.filter(f => f.properties.n > 0);
    const hot = active.filter(f => f.properties.t >= 0.7).length;
    const photos = d3.sum(active, f => f.properties.n);
    el.textContent = `${photos.toLocaleString()} photos · ${active.length.toLocaleString()} cells · ${hot} high-density`;
  }

  // ---------- chart sizing helper ----------
  function chartSize(containerEl, opts = {}) {
    const r = containerEl.getBoundingClientRect();
    const width = Math.max(280, Math.floor(r.width) || 720);
    const containerH = Math.floor(r.height);
    const fallback = opts.minHeight || 320;
    const height = containerH > 40 ? containerH : fallback;
    return { width, height };
  }

  // ---------- scatter: origin-level HDI vs first-trip remoteness, ----------
  // ---------- faceted by in-scope region, with the ESTIMATED slopes ----------
  function renderScatter() {
    const container = document.getElementById('scatter-chart');
    if (!container) return;
    container.innerHTML = '';
    const { width, height } = chartSize(container, { minHeight: 320 });
    const chartH = Math.max(180, height - 44);

    // facet order: the two significant regions first
    const FACETS = ['Europe', 'Latin America', 'East Asia', 'Southeast Asia'];
    const headline = REAL.headline.filter(h => FACETS.includes(h.region));
    const dots = REAL.origins.filter(o => FACETS.includes(o.region));

    // the estimated within-region fit: line through (x_mean, y_mean) with the
    // headline slope (beta is per +CONTRAST HDI -> per-unit = beta/CONTRAST),
    // plus a CI wedge between the lo/hi slopes. These ARE the published
    // estimates — not a refit of the origin dots.
    const C = REAL.contrast;
    const lines = [];
    const bands = [];
    for (const h of headline) {
      for (let k = 0; k <= 20; k++) {
        const x = h.x_min + (k / 20) * (h.x_max - h.x_min);
        const y = h.y_mean + (h.beta / C) * (x - h.x_mean);
        lines.push({ region: h.region, x, y, significant: h.significant });
        bands.push({
          region: h.region, x,
          y1: h.y_mean + (h.lo / C) * (x - h.x_mean),
          y2: h.y_mean + (h.hi / C) * (x - h.x_mean)
        });
      }
    }
    const labels = headline.map(h => ({
      region: h.region,
      text: `β ${h.beta >= 0 ? '+' : ''}${h.beta.toFixed(3)} / +${C.toFixed(2)} HDI` +
            (h.significant ? ` · p=${h.p.toFixed(3)}` : ' · n.s.')
    }));

    const plot = Plot.plot({
      width,
      height: chartH,
      marginLeft: 56,
      marginRight: 18,
      marginTop: 34,
      marginBottom: 60,
      style: { background: 'transparent', fontFamily: 'inherit', fontSize: '12px' },
      fx: { label: null, padding: 0.08, domain: FACETS },
      x: {
        label: 'Origin country HDI →',
        domain: [0.55, 1.0],
        grid: true,
        labelOffset: 38
      },
      y: {
        label: '↑ Mean first-trip remoteness',
        domain: [0, 0.45],
        grid: true
      },
      color: {
        legend: true,
        domain: REGION_DOMAIN,
        range: REGION_COLORS,
        label: 'Origin region'
      },
      marks: [
        Plot.frame({ stroke: '#E5E3DC' }),
        Plot.areaY(bands, {
          fx: 'region', x: 'x', y1: 'y1', y2: 'y2',
          fill: '#1A1A1A', fillOpacity: 0.07
        }),
        Plot.dot(dots, {
          fx: 'region',
          x: 'hdi',
          y: 'y_first',
          r: (d) => Math.sqrt(d.n),
          stroke: 'region',
          fill: 'region',
          fillOpacity: 0.35,
          strokeOpacity: 0.8
        }),
        Plot.line(lines.filter(d => d.significant), {
          fx: 'region', x: 'x', y: 'y',
          stroke: '#1A1A1A', strokeWidth: 2.2
        }),
        Plot.line(lines.filter(d => !d.significant), {
          fx: 'region', x: 'x', y: 'y',
          stroke: '#8A8A8A', strokeWidth: 1.6, strokeDasharray: '4,4'
        }),
        Plot.text(labels, {
          fx: 'region', text: 'text',
          frameAnchor: 'top-left', dx: 6, dy: 6,
          fill: '#1A1A1A', fontSize: 11, fontWeight: 600
        }),
        Plot.tip(dots, Plot.pointer({
          fx: 'region',
          x: 'hdi',
          y: 'y_first',
          title: (d) =>
            `${d.name} (${d.iso}) · HDI ${d.hdi.toFixed(3)}\n`
            + `${d.n} travelers (dot area ∝ n)\n`
            + `Mean first-trip remoteness: ${d.y_first.toFixed(3)}`
        }))
      ]
    });

    container.appendChild(plot);
  }

  // ---------- forest: within-region slopes vs the pooled ladder ----------
  // Slide 7's point drawn from the recorded numbers: the four within-region
  // betas (REAL.headline) and the four pooled rungs (REAL.ladder) on one
  // shared axis — opposite-signed regional effects collapse to a pooled null.
  function renderForest() {
    const withinEl = document.getElementById('forest-within');
    const pooledEl = document.getElementById('forest-pooled');
    if (!withinEl || !pooledEl) return;
    withinEl.innerHTML = '';
    pooledEl.innerHTML = '';

    const REG_ORDER = ['Europe', 'Latin America', 'East Asia', 'Southeast Asia'];
    const within = REG_ORDER
      .map(reg => REAL.headline.find(h => h.region === reg))
      .filter(Boolean)
      .map(h => ({
        row: h.region, ate: h.beta, lo: h.lo, hi: h.hi,
        color: REGION_COLORS[REGION_DOMAIN.indexOf(h.region)],
        emph: h.significant,
        note: `${h.beta >= 0 ? '+' : ''}${h.beta.toFixed(3)}` +
              (h.significant ? ` · p=${h.p.toFixed(3)}` : ' · n.s.')
      }));
    const width = Math.max(300, Math.floor(
      withinEl.closest('.forest-stack').getBoundingClientRect().width) - 34);
    const narrow = width < 600;
    const RUNG_SHORT = narrow
      ? { 1: 'OLS', 2: 'DML — linear', 3: "DML — 'auto' ◆", 4: 'DML — tuned' }
      : { 1: 'OLS adjustment',
          2: 'DML — linear nuisances',
          3: "DML — 'auto' (pre-registered)",
          4: 'DML — Optuna-tuned' };
    const pooled = REAL.ladder.map(r => ({
      row: RUNG_SHORT[r.rung] || r.label, ate: r.ate, lo: r.lo, hi: r.hi,
      color: r.rung === 3 ? '#1A1A1A' : '#8A8A8A',
      emph: r.rung === 3,
      note: `${r.ate >= 0 ? '+' : ''}${r.ate.toFixed(3)} · n.s.`
    }));

    const all = within.concat(pooled);
    const pad = 0.012;
    const domain = [Math.min(...all.map(d => d.lo)) - pad,
                    Math.max(...all.map(d => d.hi)) + pad];
    const mL = narrow ? 128 : 215;
    const mR = narrow ? 68 : 118;

    const panel = (data, el, isBottom) => {
      const plot = Plot.plot({
        width,
        height: data.length * (narrow ? 30 : 34) + (isBottom ? 58 : 16),
        marginLeft: mL, marginRight: mR,
        marginTop: 8, marginBottom: isBottom ? 46 : 8,
        style: { background: 'transparent', fontFamily: 'inherit',
                 fontSize: narrow ? '10px' : '12px' },
        x: { domain, grid: true, label: isBottom
               ? `Effect on first-trip remoteness per +${REAL.contrast.toFixed(2)} HDI →`
               : null, ticks: isBottom ? undefined : [], labelOffset: 34 },
        y: { domain: data.map(d => d.row), label: null },
        marks: [
          Plot.frame({ stroke: '#E5E3DC' }),
          Plot.ruleX([0], { stroke: '#1A1A1A', strokeDasharray: '3,3',
                            strokeOpacity: 0.55 }),
          Plot.ruleY(data, { y: 'row', x1: 'lo', x2: 'hi', stroke: 'color',
                             strokeWidth: (d) => d.emph ? 2.4 : 1.6 }),
          Plot.dot(data, { y: 'row', x: 'ate', fill: 'color',
                           r: (d) => d.emph ? 5.5 : 4 }),
          Plot.text(data, { y: 'row', x: 'hi', text: 'note', dx: 7,
                            textAnchor: 'start', fill: '#6B6B6B',
                            fontSize: narrow ? 8.5 : 10,
                            fontWeight: (d) => d.emph ? 700 : 400 }),
          Plot.tip(data, Plot.pointer({
            y: 'row', x: 'ate',
            title: (d) => `${d.row}\n${d.ate >= 0 ? '+' : ''}${d.ate.toFixed(4)} ` +
                          `[${d.lo.toFixed(4)}, ${d.hi.toFixed(4)}] per +${REAL.contrast.toFixed(2)} HDI`
          }))
        ]
      });
      el.appendChild(plot);
    };
    panel(within, withinEl, false);
    panel(pooled, pooledEl, true);
  }

  // ---------- heterogeneity: mean first-trip remoteness by origin region ----------
  function renderHetero() {
    const container = document.getElementById('hetero-chart');
    if (!container) return;
    container.innerHTML = '';
    const { width, height } = chartSize(container, { minHeight: 320 });
    const chartH = Math.max(180, height);

    const rows = REAL.gate.filter(g => g.y_first !== null);
    rows.sort((a, b) => b.y_first - a.y_first);
    const cohortMean = d3.sum(rows, r => r.y_first * r.users) / d3.sum(rows, r => r.users);

    const plot = Plot.plot({
      width,
      height: chartH,
      marginLeft: 150,
      marginRight: 18,
      marginTop: 30,
      marginBottom: 50,
      style: { background: 'transparent', fontFamily: 'inherit', fontSize: '12px' },
      x: { label: 'Mean first-trip remoteness →  (off-path score, 0–1)', domain: [0, 0.32], grid: true, labelOffset: 36 },
      y: { label: null, domain: rows.map(r => r.region) },
      color: {
        legend: true,
        domain: ['Long-haul', 'Regional'],
        range: [GROUP_COLORS['Long-haul'], GROUP_COLORS['Regional']],
        label: 'Traveler group'
      },
      marks: [
        Plot.frame({ stroke: '#E5E3DC' }),
        Plot.barX(rows, {
          x: 'y_first',
          y: 'region',
          fill: 'group',
          fillOpacity: (d) => d.in_scope ? 0.92 : 0.40,
          stroke: 'group',
          strokeWidth: 0.4
        }),
        Plot.text(rows, {
          x: 'y_first',
          y: 'region',
          text: (d) => `n=${d.users}${d.in_scope ? '' : ' · descriptive only'}`,
          dx: 6, textAnchor: 'start',
          fill: '#6B6B6B', fontSize: 10
        }),
        Plot.ruleX([0]),
        Plot.ruleX([cohortMean], { stroke: '#999', strokeDasharray: '2,3' }),
        Plot.text([{ x: cohortMean, label: 'cohort mean' }], {
          x: 'x',
          y: () => rows[0].region,
          text: 'label',
          dy: -14,
          textAnchor: 'start',
          dx: 4,
          fill: '#999',
          fontSize: 10
        })
      ]
    });

    container.appendChild(plot);
  }

  // ---------- slide navigation + auto-advance ----------
  function setupDeck(mapHandles) {
    const deck = document.getElementById('deck');
    const slides = Array.from(deck.querySelectorAll('.slide'));
    const dotsContainer = document.getElementById('deck-dots');
    const prevBtn = document.getElementById('nav-prev');
    const nextBtn = document.getElementById('nav-next');
    const toggleBtn = document.getElementById('nav-toggle');
    const heroCta = document.getElementById('hero-cta');
    const progress = document.getElementById('progress-fill');

    // auto-advance state
    const AUTO_INTERVAL_MS = 7000;
    const LAST_SLIDE_PAUSE_MS = 14000;
    let autoTimer = null;
    let autoEnabled = true;
    let hoverPaused = false;

    // build dots
    dotsContainer.innerHTML = '';
    slides.forEach((s, i) => {
      const li = document.createElement('li');
      const btn = document.createElement('button');
      btn.textContent = String(i + 1);
      btn.setAttribute('aria-label', `Go to slide ${i + 1}`);
      btn.setAttribute('role', 'tab');
      btn.addEventListener('click', () => goTo(i, 'manual'));
      li.appendChild(btn);
      dotsContainer.appendChild(li);
    });
    const dotButtons = Array.from(dotsContainer.querySelectorAll('button'));

    function currentIndex() {
      const w = deck.clientWidth || window.innerWidth;
      return Math.round(deck.scrollLeft / w);
    }

    function goTo(i, source = 'auto') {
      const clamped = Math.max(0, Math.min(slides.length - 1, i));
      const target = slides[clamped];
      deck.scrollTo({ left: target.offsetLeft, behavior: 'smooth' });
      if (source === 'manual') {
        disableAuto();
      } else {
        scheduleNext(clamped);
      }
    }

    function scheduleNext(fromIndex) {
      clearTimeout(autoTimer);
      autoTimer = null;
      if (!autoEnabled || hoverPaused) return;
      const delay = fromIndex === slides.length - 1 ? LAST_SLIDE_PAUSE_MS : AUTO_INTERVAL_MS;
      autoTimer = setTimeout(() => {
        const next = (fromIndex + 1) % slides.length;
        goTo(next, 'auto');
      }, delay);
    }

    function disableAuto() {
      autoEnabled = false;
      clearTimeout(autoTimer);
      autoTimer = null;
      toggleBtn.classList.add('paused');
      toggleBtn.setAttribute('aria-pressed', 'true');
      toggleBtn.setAttribute('aria-label', 'Resume auto-advance');
      toggleBtn.setAttribute('title', 'Resume auto-advance');
    }

    function enableAuto() {
      autoEnabled = true;
      toggleBtn.classList.remove('paused');
      toggleBtn.setAttribute('aria-pressed', 'false');
      toggleBtn.setAttribute('aria-label', 'Pause auto-advance');
      toggleBtn.setAttribute('title', 'Pause auto-advance');
      scheduleNext(currentIndex());
    }

    toggleBtn.addEventListener('click', () => {
      if (autoEnabled) disableAuto();
      else enableAuto();
    });

    function updateUI(i) {
      dotButtons.forEach((b, j) => b.classList.toggle('active', j === i));
      prevBtn.disabled = i <= 0;
      nextBtn.disabled = i >= slides.length - 1;
      const pct = slides.length > 1 ? (i / (slides.length - 1)) * 100 : 0;
      progress.style.width = pct + '%';
      if (slides[i] && slides[i].classList.contains('slide-maps') && mapHandles) {
        setTimeout(() => {
          mapHandles.longhaul.refit();
          mapHandles.regional.refit();
        }, 60);
      }
    }

    prevBtn.addEventListener('click', () => goTo(currentIndex() - 1, 'manual'));
    nextBtn.addEventListener('click', () => goTo(currentIndex() + 1, 'manual'));

    if (heroCta) {
      heroCta.addEventListener('click', () => goTo(1, 'manual'));
    }

    // keyboard navigation
    window.addEventListener('keydown', (e) => {
      const tag = (e.target && e.target.tagName) || '';
      if (tag === 'SELECT' || tag === 'INPUT' || tag === 'TEXTAREA') return;
      let handled = true;
      switch (e.key) {
        case 'ArrowRight':
        case 'PageDown':
          goTo(currentIndex() + 1, 'manual'); break;
        case 'ArrowLeft':
        case 'PageUp':
          goTo(currentIndex() - 1, 'manual'); break;
        case 'Home':
          goTo(0, 'manual'); break;
        case 'End':
          goTo(slides.length - 1, 'manual'); break;
        case ' ':
          if (autoEnabled) disableAuto(); else enableAuto();
          break;
        default:
          handled = false;
      }
      if (handled) e.preventDefault();
    });

    // touch swipe → treat as manual
    deck.addEventListener('touchstart', () => disableAuto(), { passive: true });

    // hover pause
    deck.addEventListener('mouseenter', () => {
      hoverPaused = true;
      clearTimeout(autoTimer);
      autoTimer = null;
    });
    deck.addEventListener('mouseleave', () => {
      hoverPaused = false;
      if (autoEnabled) scheduleNext(currentIndex());
    });

    // throttled scroll handler
    let raf = null;
    deck.addEventListener('scroll', () => {
      if (raf) return;
      raf = requestAnimationFrame(() => {
        raf = null;
        updateUI(currentIndex());
      });
    });

    updateUI(0);
    autoTimer = setTimeout(() => {
      if (autoEnabled && !hoverPaused) goTo(1, 'auto');
    }, 5500);

    return { currentIndex, goTo, slides };
  }

  // ---------- responsive re-render ----------
  let resizeTimer = null;
  let mapHandles = null;
  let deckHandles = null;
  function onResize() {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(() => {
      renderScatter();
      renderForest();
      renderHetero();
      if (mapHandles) {
        mapHandles.longhaul.refit();
        mapHandles.regional.refit();
      }
      if (deckHandles) {
        deckHandles.goTo(deckHandles.currentIndex());
      }
    }, 180);
  }

  // ---------- main ----------
  function init() {
    const s = REAL.summary;
    document.getElementById('trip-count').textContent =
      `${s.n_cohort.toLocaleString()} travelers · ${s.n_photos.toLocaleString()} photos`;

    const longhaul = createMap({
      mapId: 'map-longhaul', statId: 'stat-longhaul',
      labelId: 'label-longhaul', picksId: 'picks-longhaul',
      takeId: 'take-longhaul', defaults: ['EU']
    });
    const regional = createMap({
      mapId: 'map-regional', statId: 'stat-regional',
      labelId: 'label-regional', picksId: 'picks-regional',
      takeId: 'take-regional', defaults: ['EA']
    });
    mapHandles = { longhaul, regional };

    renderScatter();
    renderForest();
    renderHetero();

    document.getElementById('season-filter').addEventListener('change', (e) => {
      const season = e.target.value;
      longhaul.update(season);
      regional.update(season);
    });

    deckHandles = setupDeck(mapHandles);

    window.addEventListener('resize', onResize);
    window.addEventListener('orientationchange', onResize);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
